/* ============ A4 tools ============ */
PAGES.tools = () => {
  const L = sel(); const st = stats(L);
  let rows = toolRows(L);
  const T = S.tools;
  if (T.failOnly) rows = rows.filter((r) => r.fails > 0);
  const key = T.failOnly && T.sort === 'n' ? 'fails' : T.sort;
  rows.sort((a, b) => { const va = key === 'avg' ? parseFloat(a.avg) : a[key], vb = key === 'avg' ? parseFloat(b.avg) : b[key]; return (va - vb) * T.dir; });
  const mxn = Math.max(1, ...rows.map((r) => T.failOnly ? r.fails : r.n));
  const approvals = Math.round(sum(toolRows(L), (r) => r.n * r.ap));
  const task = toolRows(L).find((r) => r.name === 'Task');
  const th = (k, lbl, align) => '<th style="text-align:' + (align || 'left') + '"><button type="button" data-act="sortTools" data-k="' + k + '">' + lbl + (T.sort === k ? (T.dir < 0 ? ' ↓' : ' ↑') : '') + '</button></th>';
  const tbody = rows.map((r) => {
    const open = T.open === r.name; const rr = rng(hash(r.name + st.n));
    const sp = Array.from({ length: 30 }, () => 2 + rr() * 12);
    let h = '<tr class="click' + (open ? ' sel' : '') + '" data-act="toggleTool" data-t="' + r.name + '"><td class="mono" style="white-space:nowrap">' + ic(open ? 'chev' : 'chevr', 12, 'display:inline;vertical-align:-1px;color:var(--ink-3)') + ' ' + r.name + '</td><td style="min-width:140px"><span class="row" style="gap:8px"><span style="height:10px;width:' + ((T.failOnly ? r.fails : r.n) / mxn * 100).toFixed(1) + '%;min-width:2px;border-radius:0 4px 4px 0;background:' + (T.failOnly ? 'var(--crit-m)' : 'var(--ink-2)') + '"></span><span class="mono" style="font-size:11.5px">' + fmt(T.failOnly ? r.fails : r.n) + '</span></span></td><td class="mono" style="text-align:right;color:' + (r.err > 0.1 ? 'var(--crit)' : 'var(--ink-3)') + ';font-weight:' + (r.err > 0.1 ? 600 : 400) + ';white-space:nowrap">' + (r.err > 0.1 ? ic('alert', 12, 'display:inline;vertical-align:-1px') + ' ' : '') + f1(r.err * 100) + '%</td><td class="mono" style="text-align:right">' + r.avg + '</td><td class="mono" style="text-align:right">' + (r.ap ? Math.round(r.ap * 100) + '%' : '—') + '</td><td>' + spark(sp, 92, 16) + '</td></tr>';
    if (open) h += '<tr><td colspan="6" style="background:var(--bg)"><div class="col" style="gap:4px;padding:4px 0 6px">' + Array.from({ length: 5 }, (_, i) => { const fail = rr() < r.err * 2.2; return '<div class="row mono" style="font-size:11.5px;gap:10px"><span style="color:var(--ink-3)">' + md(119 - i) + ' ' + hm(10 + Math.floor(rr() * 12), Math.floor(rr() * 60)) + '</span><span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">' + esc(r.cmds[Math.floor(rr() * r.cmds.length)]) + '</span><span style="color:' + (fail ? 'var(--crit)' : 'var(--good)') + '">' + (fail ? 'exit 1' : 'ok') + '</span><span style="color:var(--ink-3)">' + r.avg + '</span></div>'; }).join('') + '</div></td></tr>';
    return h;
  }).join('');
  const lvl = (p) => p < 0.05 ? 0 : p < 0.1 ? 1 : p < 0.2 ? 2 : p < 0.3 ? 3 : p < 0.45 ? 4 : 5;
  const matrix = '<svg viewBox="0 0 380 232" style="width:100%;height:auto" role="img" aria-label="工具调用转移概率矩阵"><text x="0" y="12" font-size="9.5" fill="var(--ink-3)">从 ↓ 到 →</text>' + TRANS_NAMES.map((n, j) => '<text x="' + (84 + j * 50) + '" y="12" text-anchor="middle" font-size="10.5" font-family="var(--mono)" fill="var(--ink-3)">' + n + '</text>').join('') + TRANS.map((row, i) => '<text x="0" y="' + (40 + i * 35) + '" font-size="10.5" font-family="var(--mono)" fill="var(--ink-2)">' + TRANS_NAMES[i] + '</text>' + row.map((p, j) => { const l = lvl(p); return '<g data-tf="trans|' + i + '|' + j + '"><rect x="' + (60 + j * 50) + '" y="' + (20 + i * 35) + '" width="46" height="31" rx="4" fill="var(--h' + l + ')"' + (i === 1 && j === 0 ? ' stroke="var(--ink-1)" stroke-width="2"' : '') + '/><text x="' + (83 + j * 50) + '" y="' + (40 + i * 35) + '" text-anchor="middle" font-size="11" font-weight="600" font-family="var(--mono)" fill="' + (l >= 4 ? 'var(--bg)' : 'var(--ink-1)') + '">' + Math.round(p * 100) + '</text></g>'; }).join('')).join('') + '</svg>';
  const wmx = Math.max(...WAITS.map((w) => w[1]));
  return tbar('工具调用', fmt(st.tools) + ' 次调用 · 11 种工具 · 2 个 MCP 服务', '<button type="button" class="btn" data-act="csv">' + ic('down', 14) + '导出 CSV</button><button type="button" class="btn ai" data-act="ask" data-ctx="tools">' + ic('spark', 14) + '找出可自动化的操作</button>') +
    '<div class="content" id="content">' + filterRow('<button type="button" class="chip' + (T.failOnly ? ' on' : '') + '" data-act="failOnly" aria-pressed="' + T.failOnly + '">' + ic('alert', 13) + '仅看失败</button>') +
    '<div class="stack"><div class="tiles" style="grid-template-columns:repeat(auto-fit,minmax(min(200px,100%),1fr))">' +
    [['工具调用', fmt(st.tools), '每会话 ' + Math.round(st.tools / Math.max(1, st.n)) + ' 次'], ['错误率', f1(st.err) + '%', fmt(st.errors) + ' 次失败 · 命令占 77%'], ['需要你审批', fmt(approvals), '平均等待 38 s · 约 ' + Math.round(approvals * 38 / 3600) + ' 小时被打断'], ['子代理派发', fmt(task ? task.n : 0), '平均 96 s · 最多并行 9']].map((t) => '<div class="card tile" style="cursor:default"><span style="font-size:12px;color:var(--ink-2)">' + t[0] + '</span><span class="v">' + t[1] + '</span><span class="cap" style="font-size:11.5px">' + t[2] + '</span></div>').join('') + '</div>' +
    '<div class="two" style="grid-template-columns:minmax(0,1fr) 400px"><div class="card pad"><div class="hd"><div class="grow"><span class="ct">工具明细</span><span class="cap">点列头排序 · 点行展开最近调用</span></div></div><div class="scroll-x"><table class="tbl"><thead><tr>' + th('name', '工具') + th('n', T.failOnly ? '失败次数' : '调用次数') + th('err', '错误率', 'right') + th('avg', '平均耗时', 'right') + th('ap', '需审批', 'right') + '<th>近 30 天</th></tr></thead><tbody>' + (tbody || '<tr><td colspan="6" class="cap">没有失败的调用</td></tr>') + '</tbody></table></div></div>' +
    '<div class="card pad"><div class="hd"><div class="grow"><span class="ct">调用链 · 下一步是什么</span><span class="cap">P(列 | 行)</span></div></div>' + matrix + '<div class="col" style="gap:4px;margin-top:8px;font-size:12px;line-height:1.5;color:var(--ink-2)"><span><b style="color:var(--ink-1)">最常见三步链</b> Grep → Read → Edit</span><span><b style="color:var(--ink-1)">命令之后仍是命令 31%</b>，其中一半是失败后的原样重试</span></div></div></div>' +
    '<div class="three"><div class="card pad"><div class="hd"><div class="grow"><span class="ct">失败原因</span><span class="cap">' + fmt(st.errors) + ' 次失败 · 按输出聚类</span></div></div><div class="col" style="gap:6px">' + FAILS.map((f) => '<button type="button" data-act="openFail" data-k="' + esc(f[0]) + '" style="display:grid;grid-template-columns:112px minmax(0,1fr) 34px;gap:8px;align-items:center;font-size:12px;border:0;background:none;padding:2px 0;text-align:left;width:100%"><span style="color:var(--ink-2);white-space:nowrap">' + f[0] + '</span><span style="height:8px"><span style="display:block;height:8px;width:' + (f[1] / 31 * 100).toFixed(1) + '%;border-radius:0 4px 4px 0;background:var(--ink-2)"></span></span><span class="mono" style="text-align:right;font-size:11.5px">' + f[1] + '%</span></button>' + (T.openFail === f[0] ? '<div class="mono" style="font-size:11px;padding:6px 8px;border-radius:6px;background:var(--sunken);color:var(--ink-2)">典型：' + esc(f[2]) + '</div>' : '')).join('') + '</div></div>' +
    '<div class="card pad col"><div class="hd" style="margin:0"><div class="grow"><span class="ct">审批负担</span><span class="cap">等你点「允许」的时间</span></div></div><svg viewBox="0 0 320 96" style="width:100%;height:auto" role="img" aria-label="审批等待时间分布">' + WAITS.map((w, i) => { const h = w[1] / wmx * 64; return '<rect x="' + (8 + i * 44) + '" y="' + (80 - h).toFixed(1) + '" width="24" height="' + h.toFixed(1) + '" rx="3" fill="var(--ink-2)" data-tip="' + w[0] + '：' + w[1] + ' 次"/><text x="' + (20 + i * 44) + '" y="94" text-anchor="middle" font-size="9.5" font-family="var(--mono)" fill="var(--ink-3)">' + w[0] + '</text>'; }).join('') + '<line x1="0" x2="320" y1="80" y2="80" stroke="var(--line)"/><text x="64" y="12" text-anchor="middle" font-size="10.5" font-weight="700" font-family="var(--mono)" fill="var(--ink-1)">268</text></svg><div class="row" style="padding:8px 10px;border-radius:8px;background:var(--sunken);margin-top:auto;flex-wrap:wrap"><span style="flex:1;min-width:160px;font-size:12px;line-height:1.45;color:var(--ink-2)"><b style="color:var(--ink-1)">212 次</b>只读命令可自动放行</span>' + (S.installed.has('ro-allow') ? '<span class="tag">已安装</span>' : '<button type="button" class="btn sm p" data-act="install" data-id="ro-allow">生成白名单 Hook</button>') + '</div></div>' +
    '<div class="card pad col" style="gap:8px"><span class="ct">MCP 与子代理</span><div class="row" style="font-size:12px"><span class="mono" style="width:92px">mcp·browser</span><span style="flex:1;color:var(--ink-2)">64 次 · 失败 7.8%</span><span class="tag">在用</span></div>' + (S.installed.has('remove-figma') ? '<div class="row" style="font-size:12px;color:var(--ink-3)"><span class="mono" style="width:92px;text-decoration:line-through">mcp·figma</span><span style="flex:1">已移除 · 可在资源库重装</span></div>' : '<div class="row" style="font-size:12px"><span class="mono" style="width:92px">mcp·figma</span><span style="flex:1;color:var(--ink-2)">0 次 · 常驻 ≈ 2.1k tokens</span><button type="button" class="btn sm" data-act="install" data-id="remove-figma">移除</button></div>') + '<div style="height:1px;background:var(--hair)"></div><div style="font-size:12px;color:var(--ink-2)">子代理派发 <b style="color:var(--ink-1)">' + fmt(task ? task.n : 0) + '</b> 次 · 单次最多并行 <b style="color:var(--ink-1)">9</b> 个</div><div class="row" style="align-items:flex-end;gap:10px;height:44px">' + [[210, '并行 1'], [41, '2–3'], [12, '4–6'], [3, '7–9']].map((f) => '<div class="col" style="align-items:center;gap:3px;width:54px"><span class="mono" style="font-size:10.5px;color:var(--ink-2)">' + f[0] + '</span><span style="width:22px;height:' + Math.max(3, Math.round(f[0] / 210 * 24)) + 'px;border-radius:4px 4px 0 0;background:var(--ink-2)"></span><span class="mono cap" style="font-size:10px">' + f[1] + '</span></div>').join('') + '</div><div class="row" style="align-items:flex-start;gap:5px;font-size:11.5px;line-height:1.45;color:var(--crit)">' + ic('alert', 13, 'margin-top:1px') + '并行 ≥ 4 的派发有 40% 被你中途停止</div></div></div></div></div>';
};
TIPS.trans = (i, j) => '<b>' + TRANS_NAMES[+i] + ' → ' + TRANS_NAMES[+j] + '</b>\n条件概率 ' + Math.round(TRANS[+i][+j] * 100) + '%\n样本 ' + Math.round(TRANS[+i][+j] * 1400) + ' 次转移';
Object.assign(ACT, {
  sortTools: (el) => { const k = el.dataset.k; if (S.tools.sort === k) S.tools.dir *= -1; else { S.tools.sort = k; S.tools.dir = k === 'name' ? 1 : -1; } render(); },
  toggleTool: (el) => { S.tools.open = S.tools.open === el.dataset.t ? null : el.dataset.t; render(); },
  failOnly: () => { S.tools.failOnly = !S.tools.failOnly; render(); },
  openFail: (el) => { S.tools.openFail = S.tools.openFail === el.dataset.k ? null : el.dataset.k; render(); },
  csv: () => openCSV()
});

